"""Dispatch for native RMSNorm CuTe kernels."""

import re

import torch

from kestrel_kernels.cubin_runtime import CubinFamily
from kestrel_kernels.fallback import (
    ceil_div,
    flatten_rows_view,
    is_cute_jit_enabled,
    warn_and_run_fallback,
)
from kestrel_kernels.rmsnorm.config import (
    ADD_RMSNORM_HIDDEN_SIZES,
    GENERATED_RMSNORM_HIDDEN_SIZES,
    RMSNORM_CONFIGS,
    RMSNORM_HIDDEN_SIZES,
    RmsNormConfig,
    STRIDED4D_RMSNORM_HIDDEN_SIZES,
    rmsnorm_config_for_device,
    rmsnorm_variant_key,
)
from kestrel_kernels.rmsnorm.fallback import add_rmsnorm_torch, rmsnorm_torch

_family = CubinFamily("rmsnorm")
_ENABLE_JIT = is_cute_jit_enabled()


_VARIANT_RE = re.compile(
    r"^(?P<op>rmsnorm|add_rmsnorm)_bf16_"
    r"(?P<weight>wbf16|wfp32)_d(?P<hidden>[1-9][0-9]*)"
    r"(?:_(?P<target>sm[0-9]+))?(?P<rank4>_rank4)?_eps1e-6$"
)


def _parse_variant_key(variant_key: str) -> tuple[str, str, int, str | None, bool]:
    match = _VARIANT_RE.fullmatch(variant_key)
    if match is None:
        raise ValueError(f"unknown RMSNorm variant {variant_key!r}")
    return (
        match.group("op"),
        {"wbf16": "bfloat16", "wfp32": "float32"}[match.group("weight")],
        int(match.group("hidden")),
        match.group("target"),
        match.group("rank4") is not None,
    )


def _compile_config(
    hidden_size: int,
    target_arch: str | None,
    device_index: int | None,
) -> RmsNormConfig:
    if target_arch is None:
        if hidden_size in GENERATED_RMSNORM_HIDDEN_SIZES:
            raise ValueError(
                f"generated RMSNorm H={hidden_size} requires a target-qualified variant"
            )
        try:
            return RMSNORM_CONFIGS[hidden_size]
        except KeyError as exc:
            raise ValueError(
                f"unsupported RMSNorm hidden size {hidden_size}"
            ) from exc
    if device_index is None:
        raise ValueError(
            f"target-qualified RMSNorm variant {target_arch} requires a CUDA device"
        )
    resolved = rmsnorm_config_for_device(hidden_size, device_index)
    if resolved is None:
        raise ValueError(
            f"target-qualified RMSNorm variant {target_arch} has no "
            "calibration for the CUDA device"
        )
    config, device_target_arch = resolved
    if device_target_arch != target_arch:
        raise ValueError(
            f"RMSNorm variant target {target_arch} does not match "
            f"CUDA device target {device_target_arch}"
        )
    return config


if _ENABLE_JIT:
    from scripts.precompile import cubin_bundles as _cubin_bundles


def _compile_variant(variant_key: str, *, device_index: int | None = None):
    op, weight_dtype, hidden_size, target_arch, rank4 = _parse_variant_key(
        variant_key
    )
    config = _compile_config(hidden_size, target_arch, device_index)
    num_threads, threads_per_row = config
    if rank4:
        if op != "rmsnorm":
            raise ValueError(f"unknown RMSNorm variant {variant_key!r}")
        if hidden_size not in STRIDED4D_RMSNORM_HIDDEN_SIZES:
            raise ValueError(f"unknown RMSNorm variant {variant_key!r}")
        return _cubin_bundles._compile_rmsnorm_strided4d(
            hidden_size=hidden_size,
            eps=1.0e-6,
            num_threads=num_threads,
            threads_per_row=threads_per_row,
            weight_dtype=weight_dtype,
        )
    if op == "rmsnorm":
        compile_kernel = _cubin_bundles._compile_rmsnorm
    elif op == "add_rmsnorm" and hidden_size in ADD_RMSNORM_HIDDEN_SIZES:
        compile_kernel = _cubin_bundles._compile_add_rmsnorm
    else:
        raise ValueError(f"unknown RMSNorm variant {variant_key!r}")
    return compile_kernel(
        hidden_size=hidden_size,
        eps=1.0e-6,
        num_threads=num_threads,
        threads_per_row=threads_per_row,
        weight_dtype=weight_dtype,
    )


def _ensure_variant(
    variant_key: str,
    x: torch.Tensor,
    config: RmsNormConfig,
) -> bool:
    device_index = int(x.device.index or 0)
    if (variant_key, device_index) in _family._handles:
        return True
    if _family.is_available(variant_key):
        return True
    if not _ENABLE_JIT:
        return False
    _cubin_bundles.jit_compile_and_install(
        family=_family,
        variant_key=variant_key,
        compile_fn=_compile_variant(variant_key, device_index=device_index),
        block_x=config.num_threads,
        device_index=device_index,
    )
    return True


def _is_aligned(tensor: torch.Tensor, alignment: int = 16) -> bool:
    return tensor.data_ptr() % alignment == 0


def _strides_divisible(tensor: torch.Tensor, dims: range, divisor: int = 8) -> bool:
    return all(int(tensor.stride(dim)) % divisor == 0 for dim in dims)


def _same_cuda_device(*tensors: torch.Tensor) -> bool:
    return (
        bool(tensors)
        and all(tensor.is_cuda for tensor in tensors)
        and all(tensor.device == tensors[0].device for tensor in tensors[1:])
    )


def rmsnorm_into(
    out: torch.Tensor,
    x: torch.Tensor,
    weight: torch.Tensor,
    eps: float = 1.0e-6,
) -> None:
    if x.ndim == 0:
        raise ValueError("x must have at least one dimension")
    if out.shape != x.shape:
        raise ValueError(f"out must match x shape {tuple(x.shape)}, got {tuple(out.shape)}")
    if weight.shape != (x.shape[-1],):
        raise ValueError(f"weight shape must be {(x.shape[-1],)}, got {tuple(weight.shape)}")
    if x.numel() == 0:
        return
    if torch.compiler.is_compiling():
        rmsnorm_torch(x, weight, eps, out=out)
        return

    hidden_size = int(x.shape[-1])
    weight_key = "wbf16" if weight.dtype == torch.bfloat16 else "wfp32"
    common_candidate = (
        hidden_size in RMSNORM_HIDDEN_SIZES
        and _same_cuda_device(x, out, weight)
        and x.dtype == torch.bfloat16
        and out.dtype == torch.bfloat16
        and weight.dtype in (torch.bfloat16, torch.float32)
        and weight.stride(0) == 1
        and abs(float(eps) - 1.0e-6) < 1.0e-12
        and x.stride(-1) == 1
        and out.stride(-1) == 1
    )
    if common_candidate:
        try:
            flat_x = flatten_rows_view(x)
            flat_out = flatten_rows_view(out)
        except ValueError:
            flat_candidate = False
        else:
            flat_candidate = (
                _is_aligned(flat_x)
                and _is_aligned(flat_out)
                and _is_aligned(weight)
                and int(flat_x.stride(0)) % 8 == 0
                and int(flat_out.stride(0)) % 8 == 0
            )
    else:
        flat_candidate = False
    rank4_candidate = (
        common_candidate
        and x.ndim == 4
        and out.ndim == 4
        and hidden_size in STRIDED4D_RMSNORM_HIDDEN_SIZES
        and _is_aligned(x)
        and _is_aligned(out)
        and _is_aligned(weight)
        and _strides_divisible(x, range(0, 3))
        and _strides_divisible(out, range(0, 3))
    )
    config = None
    target_arch = None
    if flat_candidate or rank4_candidate:
        resolved = rmsnorm_config_for_device(
            hidden_size, int(x.device.index or 0)
        )
        if resolved is not None:
            config, target_arch = resolved
    flat_variant_key = (
        rmsnorm_variant_key(
            op="rmsnorm",
            weight_key=weight_key,
            hidden_size=hidden_size,
            target_arch=target_arch,
        )
        if config is not None
        else None
    )
    flat_supported = (
        config is not None
        and flat_candidate
        and flat_variant_key is not None
        and _ensure_variant(flat_variant_key, x, config)
    )

    if flat_supported:
        assert config is not None
        assert flat_variant_key is not None
        num_threads, threads_per_row = config
        rows_per_block = num_threads // threads_per_row
        dispatch = _family.resolve_dispatch(
            flat_out,
            variant_key=flat_variant_key,
            grid_x=ceil_div(flat_x.shape[0], rows_per_block),
        )
        dispatch(flat_out, flat_x, weight)
        return

    if config is not None and rank4_candidate:
        variant_key = rmsnorm_variant_key(
            op="rmsnorm",
            weight_key=weight_key,
            hidden_size=hidden_size,
            target_arch=target_arch,
            rank4=True,
        )
        if (
            _ensure_variant(variant_key, x, config)
        ):
            num_threads, threads_per_row = config
            rows_per_block = num_threads // threads_per_row
            rows = int(x.shape[0]) * int(x.shape[1]) * int(x.shape[2])
            dispatch = _family.resolve_dispatch(
                out,
                variant_key=variant_key,
                grid_x=ceil_div(rows, rows_per_block),
            )
            dispatch(out, x, weight)
            return

    warn_and_run_fallback(
        kernel_key="rmsnorm",
        message=(
            "kestrel-kernels: no native RMSNorm variant for "
            f"x={tuple(x.shape)} dtype={x.dtype}; using PyTorch fallback."
        ),
        fallback=rmsnorm_torch,
        kwargs={"x": x, "weight": weight, "eps": eps, "out": out},
    )


def rmsnorm(
    x: torch.Tensor,
    weight: torch.Tensor,
    eps: float = 1.0e-6,
) -> torch.Tensor:
    if torch.compiler.is_compiling():
        return rmsnorm_torch(x, weight, eps)
    out = torch.empty_like(x, memory_format=torch.contiguous_format)
    rmsnorm_into(out, x, weight, eps)
    return out


def add_rmsnorm_into(
    out: torch.Tensor,
    residual: torch.Tensor,
    x: torch.Tensor,
    weight: torch.Tensor,
    eps: float = 1.0e-6,
) -> None:
    if residual.ndim == 0:
        raise ValueError("residual must have at least one dimension")
    if x.shape != residual.shape:
        raise ValueError(
            f"x must match residual shape {tuple(residual.shape)}, got {tuple(x.shape)}"
        )
    if out.shape != residual.shape:
        raise ValueError(
            f"out must match residual shape {tuple(residual.shape)}, got {tuple(out.shape)}"
        )
    if weight.shape != (residual.shape[-1],):
        raise ValueError(
            f"weight shape must be {(residual.shape[-1],)}, got {tuple(weight.shape)}"
        )
    if residual.numel() == 0:
        return
    if out.data_ptr() == residual.data_ptr():
        raise ValueError("out must not alias residual")
    if torch.compiler.is_compiling():
        add_rmsnorm_torch(residual, x, weight, eps, out=out)
        return

    hidden_size = int(residual.shape[-1])
    weight_key = "wbf16" if weight.dtype == torch.bfloat16 else "wfp32"
    variant_key = f"add_rmsnorm_bf16_{weight_key}_d{hidden_size}_eps1e-6"
    supported = (
        hidden_size in ADD_RMSNORM_HIDDEN_SIZES
        and _same_cuda_device(residual, x, out, weight)
        and residual.dtype == torch.bfloat16
        and x.dtype == torch.bfloat16
        and out.dtype == torch.bfloat16
        and weight.dtype in (torch.bfloat16, torch.float32)
        and weight.stride(0) == 1
        and abs(float(eps) - 1.0e-6) < 1.0e-12
        and residual.stride(-1) == 1
        and x.stride(-1) == 1
        and out.stride(-1) == 1
    )
    if supported:
        try:
            flat_residual = flatten_rows_view(residual)
            flat_x = flatten_rows_view(x)
            flat_out = flatten_rows_view(out)
        except ValueError:
            supported = False
        else:
            supported = (
                flat_residual.shape == flat_x.shape == flat_out.shape
                and _is_aligned(flat_residual)
                and _is_aligned(flat_x)
                and _is_aligned(flat_out)
                and _is_aligned(weight)
                and int(flat_residual.stride(0)) % 8 == 0
                and int(flat_x.stride(0)) % 8 == 0
                and int(flat_out.stride(0)) % 8 == 0
                and _ensure_variant(
                    variant_key,
                    residual,
                    RMSNORM_CONFIGS[hidden_size],
                )
            )

    if supported:
        num_threads, threads_per_row = RMSNORM_CONFIGS[hidden_size]
        rows_per_block = num_threads // threads_per_row
        dispatch = _family.resolve_dispatch(
            flat_out,
            variant_key=variant_key,
            grid_x=ceil_div(flat_x.shape[0], rows_per_block),
        )
        dispatch(flat_out, flat_residual, flat_x, weight)
        return

    warn_and_run_fallback(
        kernel_key="add_rmsnorm",
        message=(
            "kestrel-kernels: no native fused add+RMSNorm variant for "
            f"residual={tuple(residual.shape)} dtype={residual.dtype}; "
            "using PyTorch fallback."
        ),
        fallback=add_rmsnorm_torch,
        kwargs={
            "residual": residual,
            "x": x,
            "weight": weight,
            "eps": eps,
            "out": out,
        },
    )


def add_rmsnorm(
    residual: torch.Tensor,
    x: torch.Tensor,
    weight: torch.Tensor,
    eps: float = 1.0e-6,
) -> torch.Tensor:
    if torch.compiler.is_compiling():
        return add_rmsnorm_torch(residual, x, weight, eps)
    out = torch.empty_like(residual, memory_format=torch.contiguous_format)
    add_rmsnorm_into(out, residual, x, weight, eps)
    return out


__all__ = ["add_rmsnorm", "add_rmsnorm_into", "rmsnorm", "rmsnorm_into"]
